from author_case_common import add

add(19,1,('Eigenes vollständiges lineares Übungsmodell: P(T)=100−5(T−15), T in °C, P in Individuen innerhalb des gültigen Bereichs 15≤T≤25. Drei unabhängige Prüfpunkte sind T=16/20/24 mit P=94/77/54. Die Anpassungsdaten wurden getrennt gewonnen; keine kausale Messung.','Own complete linear practice model: P(T)=100−5(T−15), T in °C, P in individuals, valid over15≤T≤25. Independent test points are T=16/20/24 with P=94/77/54. Fitting data were separate; this is not a causal measurement.'),('Wende das Modell an, berechne Residuen und erläutere Grenzen.','Apply the model, calculate residuals, and explain limits.'),[('Vorhersagen sind 95/75/55 Individuen.','Predictions are95/75/55 individuals.'),('Beobachtung minus Vorhersage ergibt −1/+2/−1.','Observed minus predicted gives−1/+2/−1.'),('Getrennte Prüfpunkte erlauben eine Prüfung außerhalb der Anpassungsdaten.','Separate test points allow checking beyond fitting data.'),('Gute Anpassung beweist keine Temperaturkausalität; außer 15–25 °C ist Extrapolation ungesichert, und eine Datenmodellvertiefung ist kein benannter amtlicher Bioinformatikpunkt.','Good fit does not establish temperature causation; extrapolation outside15–25 °C is uncertain, and a data-model elaboration is not a named official bioinformatics point.')],('Bei T=40 liefert die Formel einen negativen Bestand. Muss eine reale Population negativ werden?','At T=40 the formula gives a negative population. Must a real population become negative?'),('Nein. Der Einsatz verlässt den gültigen Bereich und zeigt eine Modellgrenze; Bestandszahlen sind nicht negativ.','No. The application leaves the valid range and exposes a model limit; population sizes cannot be negative.'))
add(19,2,('Eigenes digitales Datenmodell: Jahre1/2/3 haben Regen R=2/4/6 und Pflanzenzahl N=20/40/60. Gleichzeitig wurde die Fläche jedes Jahr um denselben Faktor vergrößert. Ein Regressionsprogramm meldet perfekten Zusammenhang N=10R.','Own digital dataset: years1/2/3 have rainfall R=2/4/6 and plant count N=20/40/60. Sampled area also increases by the same factor each year. A regression program reports a perfect relationship N=10R.'),('Prüfe die Modellinterpretation und beschreibe eine geeignete Datenvorbereitung.','Evaluate the interpretation and describe appropriate data preparation.'),[('Der numerische Zusammenhang ist im kleinen Datensatz perfekt, aber er trennt Regen und Flächenänderung nicht.','The numerical relationship is perfect in this small dataset but does not separate rainfall and area changes.'),('Vergleichbare Dichten oder gleiche Flächen sind für einen sachlichen Bestandsvergleich nötig.','Comparable densities or equal areas are needed for meaningful population comparison.'),('Datenbereinigung muss Einheiten, fehlende Werte, Messmethode und getrennte Prüfwerte transparent erhalten.','Data preparation must transparently retain units, missing values, methods, and separate test observations.'),('Modellfit ist keine automatische kausale biologische Erklärung; Programmoutput braucht fachliche Prüfung.','Model fit is not automatically a causal biological explanation; software output needs scientific scrutiny.')],('Alle drei Punkte werden zugleich zum Anpassen und Prüfen benutzt. Ist das eine unabhängige Generalisierungsprüfung?','All three points are used both for fitting and testing. Is this an independent generalization check?'),('Nein. Neue getrennte Daten oder begründete getrennte Validierung sind erforderlich; Wiederverwendung derselben Anpassungspunkte unterschätzt die Prüfungslücke.','No. New separate data or justified separated validation are required; reusing fitting points understates the testing gap.'))

add(20,1,('Eigenes transparentes Szenariomodell: Feuchtszenario W und Trockenszenario D werden gleich gewichtet. Management A erzielt Artenindex 80/20, B 60/50; Kosten A=10, B=14. Indizes und Kosten sind fiktiv, Gewichtung ist eine politische Vorgabe, keine biologische Tatsache.','Own transparent scenario model: wet W and dry D receive equal weight. A gives species index80/20, B60/50; costs A=10, B=14. Values are fictional, and weighting is a policy assumption rather than a biological fact.'),('Vergleiche Erwartung, schlechtestes Szenario und Kosten bei expliziten Kriterien.','Compare expectation, worst-case outcome, and costs under explicit criteria.'),[('Mittlere Artenindizes sind A=50 und B=55 bei gleicher Gewichtung.','Equal-weight mean species indices are A=50 and B=55.'),('B hat das bessere Minimum 50 statt20, A geringere Kosten.','B has the better minimum50 rather than20; A costs less.'),('Wahl hängt von Risikotoleranz, Kostengrenzen und priorisierten Werten ab.','Choice depends on risk tolerance, budget limits, and prioritized values.'),('Szenarien sind bedingte Zukunftsbilder, keine garantierten Prognosen oder sicher bekannten Wahrscheinlichkeiten.','Scenarios are conditional futures, not guaranteed forecasts or necessarily known probabilities.')],('W wird mit 0,9 und D mit 0,1 gewichtet. Wie ändern sich die Mittelwerte und ist die Entscheidung dadurch rein fachlich eindeutig?','W receives weight0.9 and D0.1. What are the new means, and is the decision then uniquely scientific?'),('A=74, B=59. Gewichte und Kosten-/Risikowerte bleiben begründungsbedürftig; ein Mittelwert allein entscheidet den Wertkonflikt nicht.','A=74 and B=59. Weights and cost/risk values still need justification; a mean alone does not resolve the value conflict.'))
add(20,2,('Eigenes Landnutzungsmodell: Option X schafft Korridore, Option Y erhöht Qualität bestehender Flächen. Unter klimainduziertem Arealwechsel hilft X stärker, bei dauerhaft stationärer Zielart hilft Y stärker. Beide können Krankheiten oder Nutzungsinteressen unterschiedlich beeinflussen.','Own land-use model: X creates corridors and Y improves existing habitat quality. X helps more under climate-driven range shifts; Y helps more for a permanently stationary target species. Disease and land-use interests can be affected differently.'),('Vergleiche Optionen bedingt nach Szenario und leite überprüfbares Management ab.','Compare options conditionally by scenario and derive testable management.'),[('Arealwechsel spricht im gegebenen Modell für Erreichbarkeit geeigneter neuer Flächen.','Range shifts favor access to suitable new habitat in this model.'),('Stationäre Engpässe sprechen für Qualität der tatsächlich genutzten Flächen.','Stationary bottlenecks favor quality of habitat actually used.'),('Nebenwirkungen und Stakeholderwerte sind getrennt von den biologischen Annahmen zu nennen.','Side effects and stakeholder values must be separated from biological assumptions.'),('Monitoring und anpassbare Maßnahmen sind sinnvoll, weil Klimaszenario und artspezifische Reaktion ungewiss sind.','Monitoring and adaptable actions are useful because climate scenarios and species-specific responses remain uncertain.')],('Die Zielart kann den Korridor nicht nutzen. Darf X weiterhin allein wegen mehr Verbindung als beste Maßnahme gelten?','The target species cannot use the corridor. Can X still be best solely because connectivity is greater?'),('Nein. Funktionale Erreichbarkeit zählt, nicht bloße geometrische Verbindung; die artspezifische Szenarioprämisse ist neu zu bewerten.','No. Functional accessibility matters rather than geometric connection alone; the species-specific scenario premise must be reconsidered.'))

add(21,1,('Eigenes C3-Blattmodell: Wärme und geschlossene Spaltöffnungen verringern CO2 relativ zu O2 nahe Rubisco. Rubisco kann RuBP carboxylieren oder oxygenieren; Oxygenierung erzeugt ein zurückzugewinnendes C2-Produkt. Keine exakten realen Flusswerte.','Own C3 leaf model: heat and closed stomata lower CO2 relative to O2 near Rubisco. Rubisco can carboxylate or oxygenate RuBP; oxygenation yields a C2 product requiring recovery. No exact real fluxes are supplied.'),('Erkläre Photorespiration und ihre stofflichen/energetischen Folgen.','Explain photorespiration and its material/energy consequences.'),[('Rubisco-Oxygenierung konkurriert mit produktiver CO2-Fixierung.','Rubisco oxygenation competes with productive CO2 fixation.'),('Rückgewinnung des C2-Produkts benötigt gekoppelte Wege über mehrere Organellen.','Recovery of the C2 product needs linked routes across several organelles.'),('Der Prozess verbraucht Energie und kann bereits gebundenen Kohlenstoff als CO2 freisetzen.','The process consumes energy and can release previously fixed carbon as CO2.'),('Photorespiration ist nicht einfach die gesamte mitochondriale Zellatmung und wirkt kontextabhängig auf Nettokohlenstoffgewinn.','Photorespiration is not simply overall mitochondrial respiration and affects net carbon gain contextually.')],('Mehr CO2 bei sonst gleichen Bedingungen senkt Oxygenierung. Warum bedeutet dies keine generelle Abschaltung der Zellatmung?','Extra CO2 under equal conditions reduces oxygenation. Why does this not imply respiration has generally stopped?'),('Rubisco-Konkurrenz und mitochondriale ATP-/Stoffprozesse sind verschiedene Mechanismen; weniger Photorespiration bedeutet nicht fehlende Zellatmung.','Rubisco competition and mitochondrial ATP/metabolic processes are different mechanisms; less photorespiration does not mean absent respiration.'))
add(21,2,('Eigenes Vergleichsmodell: C3 hat unter Wärme wenig CO2 an Rubisco, C4 konzentriert CO2 in Bündelscheiden. Eine Behauptung nennt Photorespiration völlig funktionslos. Der Rückgewinnungsweg entfernt jedoch das sonst störende 2-Phosphoglycolat.','Own comparison: warm C3 conditions give Rubisco little CO2; C4 concentrates CO2 in bundle-sheath cells. A claim calls photorespiration completely functionless, although recovery removes otherwise disruptive2-phosphoglycolate.'),('Vergleiche Nettoeffekt und Rückgewinnungsfunktion, ohne einen universellen Nutzen zu behaupten.','Compare net effects and recovery function without claiming universal benefits.'),[('C4-Anreicherung kann Oxygenierung und damit Photorespiration vermindern.','C4 concentration can reduce oxygenation and hence photorespiration.'),('Photorespiration kostet Energie und senkt oft den Nettokohlenstoffertrag.','Photorespiration costs energy and often lowers net carbon yield.'),('Der vorhandene Salvageweg beseitigt zugleich problematische Oxygenierungsprodukte und gewinnt Kohlenstoff teilweise zurück.','The salvage pathway also removes problematic oxygenation products and partially recovers carbon.'),('Kosten und Funktion sind gemeinsam zu beurteilen; der Prozess ist weder immer günstig noch vollständig sinnlos.','Costs and function must be assessed together; the process is neither always beneficial nor wholly pointless.')],('Ein Modell blockiert nur den Salvageweg, Rubisco oxygeniert weiter. Wird der Kohlenstoffverlust automatisch vollständig beseitigt?','A model blocks only the salvage pathway while Rubisco keeps oxygenating. Is carbon loss automatically eliminated?'),('Nein. Das störende Produkt kann sich ansammeln und gebundener Kohlenstoff wird nicht mehr sinnvoll zurückgewonnen; Blockade ist keine kostenfreie Reparatur.','No. Disruptive product can accumulate and fixed carbon is no longer usefully recovered; blockade is not a cost-free repair.'))

add(22,1,('Eigenes Calvin-Regulationsmodell: Licht erhöht ATP/NADPH-Verfügbarkeit und aktiviert bestimmte stromale Enzyme über Redoxregulation. Im Dunkeln fällt der Zyklusfluss trotz CO2. Geschlossene Spaltöffnungen können ihn bei Licht ebenfalls begrenzen.','Own Calvin-regulation model: light raises ATP/NADPH supply and activates certain stromal enzymes through redox regulation. In darkness cycle flux decreases despite CO2. Closed stomata can also limit flux in light.'),('Analysiere Energieversorgung, Enzymzustand und CO2-Angebot als getrennte Stellgrößen.','Analyze energy supply, enzyme state, and CO2 supply as distinct controls.'),[('ATP und NADPH liefern Energie beziehungsweise Reduktionskraft für Calvin-Schritte.','ATP and NADPH supply energy and reducing power for Calvin steps.'),('Lichtabhängige Redoxregulation kann Enzymaktivität passend zur Versorgung ändern.','Light-linked redox regulation can adjust enzyme activity to supply.'),('CO2-Mangel begrenzt die Fixierung auch bei aktivierten Enzymen.','CO2 shortage limits fixation even with activated enzymes.'),('Lichtunabhängig ist keine Aussage völliger Unabhängigkeit vom Lichtkontext; mehrere Stellgrößen wirken zusammen.','Light-independent does not mean complete independence from illumination context; several controls interact.')],('Ein Modell ergänzt im Dunkeln ATP/NADPH, lässt das benötigte Enzym aber inaktiv. Muss der normale Fluss zurückkehren?','A model supplies ATP/NADPH in darkness but leaves a required enzyme inactive. Must normal flux return?'),('Nein. Energie-/Reduktionsversorgung allein ersetzt die erforderliche katalytische Aktivität und weitere Substratbedingungen nicht.','No. Energy/reducing supply alone cannot replace required catalytic activity and other substrate conditions.'))
add(22,2,('Eigenes kontrolliertes Modell: Bei konstantem CO2/ATP/NADPH steigt Calvin-Fluss zunächst mit Temperatur und sinkt nach starker Erwärmung. Enzymstruktur wird bei hoher Temperatur beeinträchtigt. Die Netto-Gasaustauschmessung enthält zusätzlich Atmung.','Own controlled model: with fixed CO2/ATP/NADPH, Calvin flux initially rises with temperature then falls under strong heating. High temperature affects enzyme structure. Net gas exchange also includes respiration.'),('Analysiere die Form der Reaktion und Grenzen eines Nettosignals.','Analyze the response shape and limits of a net signal.'),[('Moderate Erwärmung kann Reaktionsgeschwindigkeit steigern, ohne unbegrenzte Fortsetzung.','Moderate warming can increase reaction rates without unlimited continuation.'),('Beeinträchtigte Enzymstruktur kann bei stärkerer Erwärmung den Zyklusfluss senken.','Impaired enzyme structure can reduce cycle flux under stronger heating.'),('Ein Flussmaximum in diesem Modell ist kein universeller Temperaturwert aller Pflanzen.','A flux maximum in this model is not a universal temperature for all plants.'),('Netto-CO2-Austausch trennt Calvin-Fixierung und Atmung nicht ohne zusätzliche Information.','Net CO2 exchange does not separate Calvin fixation and respiration without additional information.')],('Wenn Erwärmung nur Atmung steigert und Bruttofixierung gleich bleibt, zeigt geringere Nettoaufnahme welchen Calvin-Regulationsnachweis?','If warming only raises respiration while gross fixation stays constant, what Calvin-regulation evidence does reduced net uptake give?'),('Für eine verringerte Calvin-Fixierung keinen eindeutigen Nachweis; der Effekt kann vollständig im respiratorischen Gegenfluss liegen.','It gives no unambiguous evidence of reduced Calvin fixation; the effect may lie entirely in opposing respiratory flux.'))

add(23,1,('Eigenes Netzwerkmodell: Glucose→Pyruvat→Acetyl-CoA verzweigt zu Citratzyklus und Lipidaufbau. Hoher ATP-Zustand hemmt im Modell einen frühen katabolen Enzymschritt; ADP schwächt die Hemmung. Stoffmengen sind keine Energiemengen.','Own network: glucose→pyruvate→acetyl-CoA branches into the citric acid cycle and lipid synthesis. High ATP inhibits an early catabolic enzyme in the model; ADP weakens inhibition. Substance quantities are not energy quantities.'),('Stelle Verzweigung, gemeinsamen Knoten und bedarfsabhängige Rückkopplung dar.','Represent branching, the common node, and demand-dependent feedback.'),[('Acetyl-CoA ist ein gemeinsamer Stoffknoten mit verschiedenen Folgerouten.','Acetyl-CoA is a common metabolic node with different downstream routes.'),('Abbau und Aufbau nutzen verknüpfte Zwischenprodukte, sind nicht vollständig isolierte Kreisläufe.','Breakdown and synthesis use linked intermediates rather than entirely isolated cycles.'),('ATP-Rückkopplung kann den Abbau bei geringerem Energiebedarf drosseln.','ATP feedback can reduce breakdown when energy demand is lower.'),('Ein regulativer Knoten wird durch belegten Einfluss auf Fluss charakterisiert, nicht allein durch viele eingezeichnete Pfeile.','A regulatory node is characterized by a supported influence on flux, not merely many drawn arrows.')],('Ein Zweig fällt aus. Muss der andere immer exakt den bisherigen Stofffluss übernehmen?','One branch fails. Must the other always take exactly the old flux?'),('Nein. Substrate, Enzymkapazität, Energiebedarf und Regulation begrenzen die Umlenkung; Vernetzung bedeutet keine automatische unbegrenzte Kompensation.','No. Substrates, enzyme capacity, demand, and regulation constrain rerouting; connectivity does not imply automatic unlimited compensation.'))
add(23,2,('Eigenes Rückkopplungsnetz: S→A→B bildet Produkt P und Nebenprodukt Q über eine Verzweigung ab A. P hemmt nur das Enzym A→B. Andere Enzyme bleiben im Modell aktiv; Umleitung zu Q ist kapazitätsbegrenzt.','Own feedback network: S→A→B forms P and branch product Q from A. P inhibits only enzyme A→B. Other enzymes remain active; rerouting to Q is capacity-limited.'),('Identifiziere Regulation und leite Änderungen der Flüsse begründet ab.','Identify regulation and derive justified flux changes.'),[('P erzeugt negative Rückkopplung auf seinen eigenen Produktionszweig.','P gives negative feedback to its own production branch.'),('Bei hoher P-Menge sinkt A→B; A kann zunächst ansteigen.','At high P, A→B decreases and A can initially accumulate.'),('Q-Fluss kann bei ausreichender Kapazität steigen, ist aber nicht ohne weitere Angaben quantitativ festgelegt.','Q flux can increase with available capacity but cannot be quantified without further data.'),('Regulation, Verzweigung und Materialbilanz müssen gemeinsam gedacht werden; S/A/B/P/Q sind explizite Modellstoffe.','Regulation, branching, and material balance must be considered together; S/A/B/P/Q are explicit model substances.')],('P wird entfernt. Warum kann der gehemmte Zweig wieder anlaufen, ohne neue Mutation?','P is removed. Why can the inhibited branch restart without a new mutation?'),('Reversible Enzymhemmung kann sich beim Wegfall des Regulators lösen; die kurzfristige Flussregulation ist kein notwendiger genetischer Wandel.','Reversible inhibition can cease when the regulator is removed; short-term flux regulation need not be genetic change.'))

add(24,1,('Eigenes Störungsmodell zweier Seen: Nach gleicher kurzer Störung fällt Funktion in A von100 auf90, in B auf60. A bleibt lange bei90; B kehrt nach5 Zeitschritten auf100 zurück. Artenzahl und Bedingungen wurden getrennt erfasst.','Own disturbance model of two lakes: the same brief disturbance reduces function A100→90 and B100→60. A stays at90 for long; B returns to100 after5 steps. Species numbers and conditions are recorded separately.'),('Wende Resistenz und Erholungsfähigkeit an und leite bedingte Managementziele ab.','Apply resistance and recovery and derive conditional management goals.'),[('A widersteht der unmittelbaren Störung stärker, also höhere Resistenz in diesem Indikator.','A resists the immediate disturbance more strongly, showing greater resistance for this indicator.'),('B zeigt stärkere beziehungsweise schnellere Rückkehrfähigkeit trotz größerem anfänglichem Verlust.','B shows stronger/faster recovery despite a larger initial loss.'),('Resilienz muss über gewählte Funktions-, Zustands- und Zeitkriterien operationalisiert werden.','Resilience must be operationalized through selected function, state, and time criteria.'),('Management kann Schutz vor Einbruch oder schnelle Erholung priorisieren; die Wertwahl und Ursache sind explizit zu machen.','Management can prioritize preventing collapse or rapid recovery; values and causes must be made explicit.')],('B kehrt mengenmäßig zurück, aber die ursprüngliche Funktion fehlt. Beweist die gleiche Artenzahl vollständige Resilienz?','B recovers in abundance but the original function is absent. Does equal species count establish full resilience?'),('Nein. Gewählte Funktionen und Zustände müssen zurückkehren oder die adaptive Zieländerung ausdrücklich begründet werden; Artenzahl allein genügt nicht.','No. Selected functions and states must recover, or an adaptive target change must be justified explicitly; species count alone is insufficient.'))
add(24,2,('Eigenes Ökosystemmodell: Drei funktionell ähnliche Bestäuber reagieren verschieden auf Trockenheit. Diversität erlaubt unter manchen Bedingungen Ersatz; Habitatverlust trifft aber alle. Korridore, Ressourcenvielfalt und reduzierte Belastung kosten unterschiedlich viel.','Own ecosystem model: three functionally similar pollinators respond differently to drought. Diversity can provide replacement under some conditions, but habitat loss affects all. Corridors, resource diversity, and reduced stress have different costs.'),('Nutze Antwortdiversität und Engpassanalyse für begründetes resilientes Management.','Use response diversity and bottleneck analysis for reasoned resilient management.'),[('Verschiedene Reaktionen bei ähnlicher Funktion können Ausfall einzelner Arten teilweise puffern.','Different responses with similar functions can partly buffer single-species failure.'),('Eine gemeinsame starke Habitatbedrohung kann diesen Ersatzmechanismus zugleich ausschalten.','A strong shared habitat threat can disable this replacement mechanism.'),('Maßnahmen müssen funktionale Ressourcen und zentrale Bedrohungsursachen adressieren, nicht bloß Artennamen vermehren.','Measures must address functional resources and key threats rather than merely adding species names.'),('Kosten, Zeithorizont und kontrollierte Funktionsindikatoren erlauben nachvollziehbare Anpassung ohne Erfolgsgarantie.','Costs, time horizon, and controlled functional indicators allow transparent adaptation without guaranteeing success.')],('Alle zusätzlichen Arten reagieren identisch auf Trockenheit. Wächst die Antwortdiversität automatisch mit ihrer Zahl?','All added species respond identically to drought. Does response diversity automatically increase with species count?'),('Nein. Mehr Artenzahl ist nicht notwendig mehr funktionell relevante Unterschiedlichkeit der Störungsantworten.','No. More species do not necessarily provide more functionally relevant diversity of disturbance responses.'))
